import numpy as np

def f(w):    return 0.5 * (w[0]**2 + 10 * w[1]**2)
def grad(w): return np.array([w[0], 10 * w[1]])

w = np.array([2.0, 1.0]); lr = 0.05
prev = f(w)
for t in range(1, 10001):
    w = w - lr * grad(w)          # 경사 하강 한 걸음
    cur = f(w)
    if t <= 2: print(t, w, round(cur, 4))
    if prev - cur < 1e-9:         # 더 내려가지 않으면 멈춘다
        break
    prev = cur
print("stopped at", t, "w =", w.round(6))

