import numpy as np
def grad(w): return np.array([w[0], 10 * w[1]])

lr, eps = 0.05, 1e-7
for name in ("adagrad", "rmsprop"):
    w = np.array([2.0, 1.0]); s = np.zeros(2)
    for t in range(2):
        g = grad(w)
        if name == "adagrad":
            s += g * g                         # 지금까지의 제곱 합
        else:
            s = 0.9 * s + 0.1 * g * g          # 지수 이동 평균
        step = lr * g / (np.sqrt(s) + eps)
        w = w - step
        print(name, t + 1, "step", step.round(4), "w", w.round(4))

import math
a0, T = 0.1, 100
def step(t):   return a0 * 0.1 ** sum(t >= e for e in (30, 60, 90))
def cosine(t): return 0.5 * a0 * (1 + math.cos(math.pi * t / T))
def linear(t): return a0 * (1 - t / T)
def warm_cos(t, W=10):
    return a0 * t / W if t < W else 0.5 * a0 * (1 + math.cos(math.pi * (t - W) / (T - W)))
for t in (0, 5, 25, 50, 75, 100):
    print(t, *(round(f(t), 4) for f in (step, cosine, linear, warm_cos)))

import numpy as np
A = np.array([1.0, 10.0])                      # f = 0.5 * Σ A_i w_i^2 (조건수 10)
f = lambda w: 0.5 * np.sum(A * w * w)
grad = lambda w: A * w

def run(kind, lr, steps=200):
    w = np.array([2.0, 1.0]); v = np.zeros(2); s = np.zeros(2); m = np.zeros(2)
    for t in range(1, steps + 1):
        g = grad(w)
        if kind == "sgd":      w = w - lr * g
        elif kind == "momentum": v = 0.9 * v + g; w = w - lr * v
        elif kind == "nesterov": v = 0.9 * v + grad(w - lr * 0.9 * v); w = w - lr * v
        elif kind == "adagrad":  s += g * g; w = w - lr * g / (np.sqrt(s) + 1e-8)
        elif kind == "rmsprop":  s = 0.99 * s + 0.01 * g * g; w = w - lr * g / (np.sqrt(s) + 1e-8)
        elif kind == "adam":
            m = 0.9 * m + 0.1 * g; s = 0.999 * s + 0.001 * g * g
            w = w - lr * (m / (1 - 0.9**t)) / (np.sqrt(s / (1 - 0.999**t)) + 1e-8)
        if f(w) < 1e-6: return t, f(w)
    return steps, f(w)

for kind, lr in [("sgd", 0.1), ("momentum", 0.05), ("nesterov", 0.05),
                 ("adagrad", 0.5), ("rmsprop", 0.05), ("adam", 0.1)]:
    t, fv = run(kind, lr)
    print(f"{kind:9s} lr={lr:<5} steps={t:3d}  f={fv:.2e}")

